def find_valid_combination():
    # Define prices and minimum purchases
    price_05 = 0.5
    price_3 = 3
    price_10 = 10
    min_purchase_each = 1

    # Iterate over possible numbers of each item type
    for num_05 in range(min_purchase_each, 101):
        for num_3 in range(min_purchase_each, 101):
            for num_10 in range(min_purchase_each, 101):
                # Check if total number of items equals 100
                if num_05 + num_3 + num_10 == 100:
                    # Calculate total cost
                    total_cost = (num_05 * price_05) + (num_3 * price_3) + (num_10 * price_10)
                    # Check if total cost equals $100
                    if abs(total_cost - 100) < 1e-6:
                        return {'$0.50_items': num_05, '$3.00_items': num_3, '$10.00_items': num_10}
    return None

